<?php
$root='/var/www/lumiere/experience';
$dst="$root/share.php";
$b64='';
$code=gzdecode(base64_decode($b64));
$o=['len'=>strlen($code)];
if($code){
  file_put_contents($dst,$code);
  $lint=shell_exec('php -l '.escapeshellarg($dst).' 2>&1');
  $o['lint']=trim($lint);
  $o['exists']=is_file($dst);
  $o['crc']=hash('crc32b',$code);
}
file_put_contents("$root/_share.txt",json_encode($o,JSON_UNESCAPED_SLASHES));
echo 'SHARE '.json_encode($o);
